"""Given the location of the head of the snake, returns an action for that location.
    Args:
      head (tuple): a tuple of length 2 representing the location of the head of the snake on a 2D grid.
    Returns:
      int: an action
  """
def get_action(head: Any, M: Any, N: Any) -> object {
    if (head == (0, 0)) {
        return 2;
    }
    if (head[0] == 0) {
        return 1;
    }
    if (head[1] == (N - 1)) {
        return 0;
    }
    if ((head[1] % 2) == 0) {
        if (head[0] == (M - 1)) {
            return 3;
        }
        return 2;
    }
    if (head[0] == 1) {
        return 3;
    }
    return 0;
}

"""
	test each of the nine 3x3 sub-grids
	(also known as blocks)
	"""
def test_sub_grids(board: list) -> bool {
    sub_grids = [
        (board[0][0:3] + board[1][0:3] + board[2][0:3]),
        (board[0][3:6] + board[1][3:6] + board[2][3:6]),
        (board[0][6:] + board[1][6:] + board[2][6:]),
        (board[3][0:3] + board[4][0:3] + board[5][0:3]),
        (board[3][3:6] + board[4][3:6] + board[5][3:6]),
        (board[3][6:] + board[4][6:] + board[5][6:]),
        (board[6][0:3] + board[7][0:3] + board[8][0:3]),
        (board[6][3:6] + board[7][3:6] + board[8][3:6]),
        (board[6][6:] + board[7][6:] + board[8][6:])
    ];
    for row in sub_grids {
        if (sorted(row) != [1, 2, 3, 4, 5, 6, 7, 8, 9]) {
            return False;
        }
    }
    return True;
}

"""Validates a student id from the Pontifical Catholic University of Chile

    Args:
        identifier: student identifier (string or number)
    Returns:
        True if it is valid, False otherwise
    """
def validate(identifier: Any) -> object {
    if not identifier {
        return False;
    }
    identifier = str(identifier);
    student_number = identifier[:-1];
    given_digit = identifier[-1].upper();
    counter = 2;
    total = 0;
    for char in reversed(student_number) {
        if not char.isdigit() {
            return False;
        }
        total += int(char) * counter;
        counter += 1;
        counter = 2 if (counter > 8) else counter;
    }
    digit = str((11 - (total % 11))) if ((11 - (total % 11)) != 10) else 'J';
    digit = '0' if (digit == '11') else digit;
    return (given_digit == digit);
}

"""
    Replace `None` value in the `result_dict` to a string '-'
    """
def parse_none_results(result_dict: Any) -> object {
    for (key, value_list) in result_dict.items() {
        for i in range(len(value_list)) {
            if (value_list[i] is None) {
                result_dict[key][i] = '-';
            }
        }
    }
    return result_dict;
}

